-- Historical schema snapshot used to test the in-place 0001 -> 0002 upgrade.
CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TABLE organizations (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE users (id BIGSERIAL PRIMARY KEY, org_id BIGINT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','viewer')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE assets (id BIGSERIAL PRIMARY KEY, org_id BIGINT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'vehicle', device_id TEXT UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX assets_org_idx ON assets(org_id);
CREATE TABLE devices (id BIGSERIAL PRIMARY KEY, org_id BIGINT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, asset_id BIGINT NOT NULL REFERENCES assets(id) ON DELETE CASCADE, device_token_hash TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE positions (id BIGSERIAL PRIMARY KEY, org_id BIGINT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, asset_id BIGINT NOT NULL REFERENCES assets(id) ON DELETE CASCADE, lat DOUBLE PRECISION NOT NULL CHECK(lat BETWEEN -90 AND 90), lng DOUBLE PRECISION NOT NULL CHECK(lng BETWEEN -180 AND 180), speed DOUBLE PRECISION NOT NULL DEFAULT 0, heading DOUBLE PRECISION, recorded_at TIMESTAMPTZ NOT NULL, point GEOGRAPHY(POINT,4326) GENERATED ALWAYS AS (ST_SetSRID(ST_MakePoint(lng,lat),4326)::geography) STORED);
CREATE INDEX positions_asset_time_idx ON positions(asset_id,recorded_at DESC);
CREATE INDEX positions_point_idx ON positions USING GIST(point);
CREATE TABLE geofences (id BIGSERIAL PRIMARY KEY, org_id BIGINT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, shape TEXT NOT NULL CHECK(shape IN ('circle','polygon')), geometry JSONB NOT NULL, enabled BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE geofence_events (id BIGSERIAL PRIMARY KEY, org_id BIGINT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, geofence_id BIGINT NOT NULL REFERENCES geofences(id) ON DELETE CASCADE, asset_id BIGINT NOT NULL REFERENCES assets(id) ON DELETE CASCADE, event TEXT NOT NULL CHECK(event IN ('enter','exit')), occurred_at TIMESTAMPTZ NOT NULL, UNIQUE(geofence_id,asset_id,event,occurred_at));
CREATE TABLE observations (id BIGSERIAL PRIMARY KEY, org_id BIGINT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, asset_id BIGINT REFERENCES assets(id) ON DELETE SET NULL, author_id BIGINT NOT NULL REFERENCES users(id), lat DOUBLE PRECISION NOT NULL, lng DOUBLE PRECISION NOT NULL, observed_at TIMESTAMPTZ NOT NULL, note TEXT NOT NULL DEFAULT '', photo_ref TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX observations_org_time_idx ON observations(org_id,observed_at DESC);
CREATE TABLE alerts (id BIGSERIAL PRIMARY KEY, org_id BIGINT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, asset_id BIGINT REFERENCES assets(id) ON DELETE CASCADE, geofence_id BIGINT REFERENCES geofences(id) ON DELETE CASCADE, event_id BIGINT REFERENCES geofence_events(id) ON DELETE CASCADE, message TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), read_at TIMESTAMPTZ);
